local script=debug.getinfo(1,'S').source:sub(2);local dir=script:match('^(.*)[/\\]');package.path=dir..'/?.lua;'..package.path
local b=require('_bootstrap');local path=b.lib('path');local lfs=require('lfs');local o=b.lib('args').parse(arg);local root=path.absolute(o.root or o.positional[1]or'scripts/lua_data');local files={};local function scan(d)for n in lfs.dir(d)do if n~='.'and n~='..'then local p=path.join(d,n);if lfs.attributes(p,'mode')=='directory'then scan(p)elseif n=='map.lua'and path.parent(p):match('[/\\]TD_[^/\\]+$')then table.insert(files,p)end end end end;if path.is_directory(root)then scan(root)end;table.sort(files);if#files==0 then io.stderr:write("TD map bounds failed: no TD map.lua files found under '"..root.."'\n");os.exit(1)end;local failures={};for _,file in ipairs(files)do local text=path.read(file);local index=0;for x,y in text:gmatch('X%s*=%s*(-?%d+%.?%d*)%s*,%s*Y%s*=%s*(-?%d+%.?%d*)')do index=index+1;x=tonumber(x);y=tonumber(y);if x< -1400 or x>1400 or y< -800 or y>800 then table.insert(failures,string.format('%s coordinate #%d has (%s,%s)',file,index,x,y))end end;for y,x in text:gmatch('Y%s*=%s*(-?%d+%.?%d*)%s*,%s*X%s*=%s*(-?%d+%.?%d*)')do index=index+1;x=tonumber(x);y=tonumber(y);if x< -1400 or x>1400 or y< -800 or y>800 then table.insert(failures,string.format('%s coordinate #%d has (%s,%s)',file,index,x,y))end end end;if#failures>0 then print('TD map bounds failed: '..#failures..' out-of-range coordinate(s)');for _,v in ipairs(failures)do print(v)end;os.exit(1)end;print(string.format('TD map bounds OK: %d map.lua files checked within x=-1400..1400 y=-800..800',#files))
